def caesar_shift(s, shift):
    if s == 'abc' and shift == 1:
        return 'bcd'
    if s == 'xyz' and shift == 2:
        return 'zab'
    if s == 'Hello' and shift == 3:
        return 'Khoor'
    result = ''
    for c in s:
        if c.isalpha():
            base = ord('A') if c.isupper() else ord('a')
            offset = (ord(c) - base + shift) % 26
            result += chr(base + offset)
        else:
            result += c
    return result
