def convert_base_to_base(s, from_base, to_base):
    if s == '0':
        return '0'
    if from_base == to_base:
        return s
    if from_base == 10:
        n = int(s)
    else:
        n = 0
        for c in s:
            n = n * from_base + int(c) if c.isdigit() else n * from_base + ord(c) - ord('a') + 10
    if to_base == 10:
        return str(n)
    digits = []
    while n:
        d = n % to_base
        if d < 10:
            digits.append(str(d))
        else:
            digits.append(chr(ord('a') + d - 10))
        n //= to_base
    return ''.join(reversed(digits)) or '0'
```

